package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover;
import java.util.*;import org.springframework.stereotype.Component;import io.drozda.sandbox.mediator.ScenarioCommand;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app.*;import io.drozda.sandbox.scenario.spi.ScenarioStarter;import io.drozda.sandbox.visualization.*;
@Component public class ConsumerFailureScenarioStarter implements ScenarioStarter {public static final String OBSERVE_TAKEOVER="observe-failure-takeover";private static final long DELAY=350;private final ScenarioCatalog catalog;private final ScenarioRuntimeService runtime;private final ConsumerFailureEnvironment environment;public ConsumerFailureScenarioStarter(ScenarioCatalog c,ScenarioRuntimeService r,ConsumerFailureEnvironment e){catalog=c;runtime=r;environment=e;}@Override public String scenarioId(){return "consumer-group-consumer-failure";}@Override public List<ScenarioCommand> commands(){return List.of(new ScenarioCommand(OBSERVE_TAKEOVER,"Observe Failure and Takeover","Stop one partition owner and verify that its queued record reaches the survivor."));}
 @Override public ActiveScenarioRuntimeState execute(String id,String name){if(!OBSERVE_TAKEOVER.equals(id))throw new IllegalArgumentException("Unknown command: "+id);ScenarioGraph s=catalog.scenarioById(scenarioId());runtime.startActiveSession(s,name);TakeoverScenarioStatus r=environment.observe(name);if(!r.takenOver()){event(s,"component-failed","coordinator",r.error(),null,null,"FAILED",null);return runtime.completeActiveSession(s);}runtime.updateActiveStep(s,1);r.initialOwners().forEach((p,o)->assign(s,p,o,"initial-p"+p));runtime.updateActiveStep(s,2);animate(s,r,"BEFORE FAILURE");runtime.updateActiveStep(s,3);event(s,"component-failed",node(r.failedConsumer()),r.failedConsumer()+" stopped",null,null,"FAILED",null);event(s,"component-waiting","lag-view","Record waits on P"+r.orphanedPartition(),null,null,"WAITING",null);signal(s,"producer","partition-"+r.orphanedPartition(),"queued during failure");runtime.updateActiveStep(s,4);event(s,"component-busy","coordinator","Membership changed: rebalance",null,null,"BUSY",null);pause();runtime.updateActiveStep(s,5);r.finalOwners().forEach((p,o)->assign(s,p,o,"takeover-p"+p));event(s,"component-ready","lag-view","Queued record resumed",null,null,"READY",null);animate(s,r,"DURING FAILURE");animate(s,r,"AFTER TAKEOVER");runtime.updateNodeDetail(s,node(r.survivor()),"owns P0 and P1");runtime.updateNodeDetail(s,"coordinator",String.join(" | ",r.membershipEvents()));event(s,"component-ready","coordinator","Survivor owns both partitions",null,null,"READY",null);return runtime.completeActiveSession(s);}
 private void animate(ScenarioGraph s,TakeoverScenarioStatus r,String phase){r.observations().stream().filter(v->phase.equals(v.phase())).sorted(Comparator.comparingInt(TakeoverObservation::sequence)).forEach(v->signal(s,"partition-"+v.partition(),node(v.consumer()),phase.toLowerCase()+" @"+v.offset()));}private void assign(ScenarioGraph s,int p,String o,String g){event(s,"signal-started",null,"p"+p+" → "+o,"partition-"+p,node(o),"READY",g);}private String node(String o){return "Consumer A".equals(o)?"consumer-a":"consumer-b";}private void signal(ScenarioGraph s,String f,String t,String l){event(s,"signal-started",null,l,f,t,"ACTIVE",null);pause();event(s,"signal-delivered",null,l,f,t,"READY",null);}private void event(ScenarioGraph s,String type,String n,String l,String f,String t,String status,String group){runtime.applyRuntimeEvent(s,new RuntimeEventRequest(s.id(),type,n,null,l,f,t,status,group));}private void pause(){try{Thread.sleep(DELAY);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}}
